import{_ as n,o as t,c as a,a5 as r}from"./chunks/framework.BwlBv862.js";const f=JSON.parse('{"title":"Gérer les connexions LIVE","description":"","frontmatter":{"title":"Gérer les connexions LIVE","docId":"user.live.connections","translationKey":"user.live.connections","locale":"fr","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"37f7274550d3010051ab456da2a2091b650e5e7aaaf30756b6695435bcfc08c7","translationRevision":"72f34d378dffe2fb1f50b1738513b1dfe93af4a03d57c70f93c76e27f0fa759f","order":10},"headers":[],"relativePath":"fr/user/live/connections.md","filePath":"fr/user/live/connections.md","lastUpdated":1794611623000}'),s={name:"fr/user/live/connections.md"};function i(o,e,l,c,u,d){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="manage-live-connections" tabindex="-1">Gérer les connexions LIVE <a class="header-anchor" href="#manage-live-connections" aria-label="Permalink to &quot;Gérer les connexions LIVE {#manage-live-connections}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objectif et prérequis <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objectif et prérequis {#goal-and-prerequisites}&quot;">​</a></h2><p>Se connecter à un créateur précis, comprendre la reconnexion et configurer les serveurs de plugins indépendamment. Il vous faut une <a href="./../installation.html">installation de bureau</a> fonctionnelle, un accès réseau et l’identifiant du créateur. Consultez les <a href="./../requirements.html">prérequis</a> avant de diagnostiquer des problèmes de système d’exploitation.</p><h2 id="connect-deliberately" tabindex="-1">Se connecter de manière délibérée <a class="header-anchor" href="#connect-deliberately" aria-label="Permalink to &quot;Se connecter de manière délibérée {#connect-deliberately}&quot;">​</a></h2><ol><li>Ouvrez <strong>Connections</strong>. Saisissez l’identifiant, avec ou sans <code>@</code> ; un nom affiché n’est pas le même identifiant.</li><li>Laissez <strong>Use Cookie</strong> désactivé au départ. Si TikTok exige une session autorisée, activez cette option et saisissez le cookie uniquement dans le champ masqué. Les cookies restent en mémoire ; ne les collez pas dans les diagnostics ou les paramètres Cloud.</li><li>Laissez <strong>Monitor and auto-connect</strong> désactivé pour une tentative directe, puis sélectionnez <strong>Connect</strong>. Lisez l’état et toute erreur avant de réessayer.</li><li>Consultez <a href="./feed.html">Live feed</a> pour vérifier le créateur et la présence d’un nouvel événement. Une salle connectée mais calme peut ne montrer aucune activité.</li><li>Utilisez <strong>Reconnect</strong> pour le même créateur ou <strong>Disconnect</strong> avant d’en changer. Pendant une tentative en cours, <strong>Cancel</strong> l’arrête.</li></ol><p>Après une connexion directe réussie, activez la surveillance pour attendre qu’un créateur passe en direct. L’attente et la vérification sont distinctes de la connexion établie. Arrêtez la surveillance avant de modifier un identifiant verrouillé. Sélectionner un créateur récent démarre une connexion ; cela ne remplit pas simplement le champ.</p><p>L’explorateur propose des salles découvertes, mais les résultats peuvent devenir obsolètes. Actualisez-les avant de supposer qu’une salle est toujours disponible. Les connexions des serveurs de plugins dans le panneau inférieur configurent leurs propres services ; un plugin connecté n’authentifie ni TikTok ni Cloud.</p><h2 id="expected-result-and-status" tabindex="-1">Résultat attendu et état <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Résultat attendu et état {#expected-result-and-status}&quot;">​</a></h2><p>Les connexions directes, la surveillance et les commandes de connexion des plugins sont disponibles. La reconnexion au même créateur conserve le contexte du flux actuel ; changer de créateur ouvre un autre contexte. L’accès réel à TikTok dépend de la salle et de la session distantes ; un test local réussi ne le garantit pas.</p><h2 id="recovery" tabindex="-1">Récupération <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Récupération {#recovery}&quot;">​</a></h2><p>Pour une salle hors ligne, vérifiez que le créateur diffuse en direct. En cas d’erreur de session ou de limitation de débit, respectez la condition de nouvelle tentative indiquée. Cliquer plusieurs fois sur la reconnexion ne renouvelle pas l’authentification. Consultez le <a href="./../preferences/troubleshooting.html">dépannage</a> pour recueillir le composant en échec et l’heure sans exposer d’identifiants.</p>',11)])])}const m=n(s,[["render",i]]);export{f as __pageData,m as default};
